import test from "node:test";
import assert from "node:assert/strict";
import {planner, apply} from "./replay.mjs";
import {bookStudio} from "./services/studio.mjs";
import {Ledger} from "./common/ledger.mjs";

const catalog = () => ({default:5, studios:new Map([["orchid",8], ["iris",3]])});
const book = (id, overrides = {}) => ({service:"studio", action:"book", id,
  tenant:"orchid", day:"2025-04-02", units:7, ...overrides});
const renew = (previous, id, overrides = {}) => ({service:"studio", action:"renew",
  previous, id, day:"2025-05-02", ...overrides});

test("studio admission preserves replay, conflicts, cancellations and tenant/day accounting", () => {
  const dispatch = planner(catalog());
  assert.deepEqual(dispatch(book("first")), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(book("first")).status, "replay");
  assert.equal(dispatch(book("first", {units:6})).status, "conflict");
  assert.deepEqual(dispatch(book("overflow", {units:2})), {status:"full", id:"overflow", remaining:1});
  assert.equal(dispatch(book("last", {units:1})).status, "booked");
  assert.equal(dispatch(book("other-day", {day:"2025-04-03"})).status, "booked");
  assert.equal(dispatch(book("other-tenant", {tenant:"rose", units:5})).status, "booked");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(book("first")).status, "cancelled");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "replay");
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:"2025-04-02"}), {units:1});
  assert.deepEqual(dispatch(book("replacement")), {status:"booked", id:"replacement", remaining:0});
  assert.equal(apply(dispatch, book("invalid", {units:0})).status, "invalid");
});

test("quotas apply to direct bookings and renewals without leaking to other desks", () => {
  const dispatch = planner(catalog());
  assert.equal(dispatch(book("small", {tenant:"iris", units:4})).status, "full");
  assert.equal(dispatch(book("unknown", {tenant:"rose", units:6})).status, "full");
  assert.equal(dispatch(book("archive", {service:"archive", units:6})).status, "full");
  assert.equal(dispatch(book("original")).status, "booked");
  const next = renew("original", "next");
  assert.deepEqual(dispatch(next), {status:"booked", id:"next", remaining:1});
  assert.equal(dispatch(next).status, "replay");
  assert.equal(dispatch({...next, units:6}).status, "conflict");
  assert.equal(dispatch(renew("original", "too-many", {units:2})).status, "full");
  assert.equal(dispatch(renew("original", "last", {units:1})).status, "booked");
  dispatch({service:"studio", action:"cancel", id:"next"});
  assert.equal(dispatch(next).status, "cancelled");
  assert.equal(dispatch(renew("next", "missing")).status, "missing");
  for (const [tenant, units] of [["iris",4], ["rose",6]]) {
    dispatch(book("import-" + tenant, {action:"import", tenant, units}));
    assert.equal(dispatch(renew("import-" + tenant, "renew-" + tenant)).status, "full");
  }
  dispatch(book("archive-source", {service:"archive", units:5}));
  assert.equal(dispatch(renew("archive-source", "archive-next", {service:"archive", units:6})).status, "full");
});

test("studio adapter keeps the shared catalog unchanged and counts imported usage", () => {
  const config = catalog();
  const ledger = new Ledger(config);
  ledger.post({id:"backfill", tenant:"orchid", day:"2025-04-02", units:2});
  assert.equal(bookStudio(ledger, book("over"), config).status, "full");
  assert.deepEqual(bookStudio(ledger, book("fit", {units:6}), config),
    {status:"booked", id:"fit", remaining:0});
  assert.equal(ledger.catalog, config);
  assert.equal(config.default, 5);
});
