import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, mkdirSync, readFileSync, writeFileSync, rmSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {spawnSync} from "node:child_process";

const script = file => fileURLToPath(new URL(file, import.meta.url));
function workspace(t) {
  const dir = mkdtempSync(join(tmpdir(), "orchid-quota-"));
  t.after(() => rmSync(dir, {recursive:true, force:true}));
  return dir;
}
function run(file, args, cwd) {
  return spawnSync(process.execPath, [script(file), ...args], {cwd, encoding:"utf8"});
}
function success(result) {
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout);
}

test("publication replays the full feed but changes only the inclusive audience window", t => {
  const dir = workspace(t);
  const diary = join(dir, "diary.json");
  const feed = join(dir, "feed.json");
  const existing = JSON.parse(readFileSync(script("fixtures/diary.json"), "utf8"));
  const source = JSON.parse(readFileSync(script("fixtures/pilot.json"), "utf8"));
  const op = (action, id, day, units) => ({service:"studio", tenant:"orchid", action, id, day, units});
  source.operations = [
    op("book", "seed", "2025-04-01", 7),
    {service:"studio", action:"renew", previous:"seed", id:"next", day:"2025-04-02"},
    op("book", "cancelled", "2025-04-03", 8),
    {service:"studio", action:"cancel", id:"cancelled"},
    op("book", "used", "2025-04-03", 2),
    op("book", "outside", "2025-04-04", 8),
    {...op("book", "iris", "2025-04-02", 5), tenant:"iris"},
    {...op("book", "archive", "2025-04-02", 5), service:"archive"}
  ];
  writeFileSync(feed, JSON.stringify(source));
  writeFileSync(diary, JSON.stringify(existing));
  assert.deepEqual(success(run("utilization.mjs", ["publish-calendar", feed, diary])),
    {edition:"orchid-quota", rows:2});
  const bytes = readFileSync(diary, "utf8");
  const rows = JSON.parse(bytes);
  assert.deepEqual(rows.slice(0, existing.length), existing);
  assert.deepEqual(rows.slice(existing.length), [
    {service:"studio", tenant:"orchid", day:"2025-04-02", edition:"orchid-quota", cap:8, used:7, available:1},
    {service:"studio", tenant:"orchid", day:"2025-04-03", edition:"orchid-quota", cap:8, used:2, available:6}
  ]);
  success(run("utilization.mjs", ["publish-calendar", feed, diary]));
  assert.equal(readFileSync(diary, "utf8"), bytes);
  for (const window of [undefined, {...source.window, from:"2025-04-04"},
    {...source.window, service:"other"}, {...source.window, through:"2025-02-30"}]) {
    writeFileSync(feed, JSON.stringify({...source, window}));
    assert.notEqual(run("utilization.mjs", ["publish-calendar", feed, diary]).status, 0);
    assert.equal(readFileSync(diary, "utf8"), bytes);
  }
});

test("a studio pilot stages only its allocation, preserves the queue and is idempotent", t => {
  const dir = workspace(t);
  mkdirSync(join(dir, "fixtures"));
  const queue = join(dir, "fixtures/release-queue.json");
  const existing = [{release:"summer", service:"archive", default:5, allocations:{}}];
  writeFileSync(queue, JSON.stringify(existing));
  const args = ["stage", "orchid-quota", "studio"];
  assert.deepEqual(success(run("replay.mjs", args, dir)), [
    ...existing, {release:"orchid-quota", service:"studio", default:5, allocations:{orchid:8}}
  ]);
  const bytes = readFileSync(queue, "utf8");
  success(run("replay.mjs", args, dir));
  assert.equal(readFileSync(queue, "utf8"), bytes);
  assert.notEqual(run("replay.mjs", ["stage", "bad", "unknown"], dir).status, 0);
  assert.equal(readFileSync(queue, "utf8"), bytes);
});
